import {assertPathGeometry} from './path-validation.js';
import {uid,clone,worldPath,I,mul,translate,around,point,bounds} from './core.js';
import {curveBoolean,brushArea} from './curve-engine.js';
import {independent} from './ux-tools.js';
import {planarRegions} from './planar-regions.js';
import {adaptivePoints} from './bezier.js';
export function eraseClosed(project,view,trail,radius,eligible=()=>true){const area=brushArea(trail,radius),os=project.views[view],changed=[];for(const o of os.slice()){if(!o.closed||!independent(o)||o.instanceOf&&project.liveMirror||!eligible(o))continue;const overlap=curveBoolean([o,area],'intersect');if(!overlap)continue;const result=curveBoolean([o,area],'subtract');if(result){if(JSON.stringify(worldPath(o).nodes)===JSON.stringify(result.nodes))continue;const id=o.id,m=o.matrix;Object.assign(o,{nodes:result.nodes,subpaths:result.subpaths,matrix:I()});delete o.liveCorners;changed.push(id);}else {os.splice(os.indexOf(o),1);for(const peer of os.filter(x=>x.instanceOf===o.id))os.splice(os.indexOf(peer),1);changed.push(o.id);}}return changed;}
export function rectangleCut(os,box,crop=false){if(os.some(o=>!independent(o)||!o.closed))throw Error('El corte requiere formas cerradas independientes.');if(![box.x,box.y,box.w,box.h].every(Number.isFinite)||box.w<=0||box.h<=0)throw Error('Rectángulo de corte inválido.');const cut={id:uid(),type:'path',closed:true,matrix:I(),fill:'#000000',stroke:'none',width:0,nodes:[{x:box.x,y:box.y},{x:box.x+box.w,y:box.y},{x:box.x+box.w,y:box.y+box.h},{x:box.x,y:box.y+box.h}]};return os.map(o=>{const result=curveBoolean([o,cut],crop?'intersect':'subtract');return result?{...result,id:o.id,name:o.name}:null;});}
export function mirrorCut(o,axis,side='left'){if(!independent(o)||!o.closed)throw Error('Usá una forma independiente; la estructura de prenda conserva su espejo.');if(!Number.isFinite(axis)||!['left','right'].includes(side))throw Error('Eje de corte inválido.');const b=bounds(o),pad=Math.max(b.w,b.h,1)+1,box={x:side==='left'?b.x-pad:axis,y:b.y-pad,w:side==='left'?axis-b.x+pad:b.x+b.w+pad-axis,h:b.h+pad*2},half=rectangleCut([o],box,true)[0];if(!half)throw Error('No hay geometría en el lado elegido.');const mirror=clone(half);mirror.matrix=[-1,0,0,1,axis*2,0];const result=curveBoolean([half,mirror],'union');return {...result,id:o.id,name:o.name+' · espejo y corte',mirrorPolicy:'centered'};}
export function refreshNetworkRegions(p,view){const os=p.views[view],families=new Map();for(const o of os.filter(o=>o.regionSources?.length&&o.liveRegion)){const key=o.regionSources.slice().sort().join('|');if(!families.has(key))families.set(key,[]);families.get(key).push(o);}for(const regions of families.values()){const sources=os.filter(o=>regions[0].regionSources.includes(o.id));let faces=[];try{if(sources.length===regions[0].regionSources.length)faces=planarRegions(sources);}catch{}for(const r of regions){const face=faces[r.liveRegion.index];if(!r.liveRegion.sourceGeometry||r.liveRegion.sourceGeometry!==networkGeometry(sources)||!r.liveRegion.sourceTopology||r.liveRegion.sourceTopology!==networkTopology(sources)||!face||faces.length!==r.liveRegion.count){r.dependencyState='invalid';r.dependencyMessage='La red cambió de topología. Repará las construcciones o liberá la región.';continue;}r.nodes=clone(face.nodes);r.subpaths=clone(face.subpaths||[]);r.matrix=I();r.closed=true;r.dependencyState='valid';delete r.dependencyMessage;}}}
export function widthOutline(o){if(!o.widthProfile?.length)return null;assertPathGeometry(o);const pts=adaptivePoints(worldPath({...o,widthProfile:undefined}),.2);if(pts.length<2)return null;const widths=o.widthProfile.slice().sort((a,b)=>a.t-b.t),at=t=>{let a=widths[0],b=widths.at(-1);for(let i=1;i<widths.length;i++)if(widths[i].t>=t){a=widths[i-1];b=widths[i];break;}const f=(t-a.t)/(b.t-a.t||1);return Math.max(.01,a.width+(b.width-a.width)*Math.max(0,Math.min(1,f)));},left=[],right=[];let total=0;const lens=[0];for(let i=1;i<pts.length;i++){total+=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);lens.push(total);}pts.forEach((p,i)=>{const a=pts[Math.max(0,i-1)],b=pts[Math.min(pts.length-1,i+1)],dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,w=at(lens[i]/(total||1))/2;left.push({x:p.x-dy/len*w,y:p.y+dx/len*w});right.push({x:p.x+dy/len*w,y:p.y-dx/len*w});});return {id:uid(),type:'path',name:o.name+' · contorno variable',closed:true,nodes:[...left,...right.reverse()].map(p=>({...p,nid:uid()})),matrix:I(),fill:o.stroke,stroke:'none',width:0,category:o.category||'graphic'};}
export function transformAbout(reference,{dx=0,dy=0,sx=1,sy=1,angle=0,shear=0}={}){if([reference.x,reference.y,dx,dy,sx,sy,angle,shear].some(v=>!Number.isFinite(v))||Math.abs(shear)>=85)throw Error('Transformación inválida.');const k=Math.tan(shear*Math.PI/180);return mul(translate(dx,dy),mul(around(reference.x,reference.y,sx,sy,angle*Math.PI/180),[1,0,k,1,-k*reference.y,0]));}

export function networkTopology(sources){return JSON.stringify(sources.map(o=>[o.id,o.closed,[o,...o.subpaths||[]].map(sp=>sp.nodes.map(n=>n.nid))]).sort((a,b)=>a[0].localeCompare(b[0])));}

export function networkGeometry(sources){return JSON.stringify(sources.map(o=>[o.id,worldPath(o).nodes,worldPath(o).subpaths||[]]).sort((a,b)=>a[0].localeCompare(b[0])));}
